const listUsers = `-- name: ListUsers :many
SELECT id, username, email, first_name, full_name, password_hash, role, status, must_change_password, last_login_at, created_at, updated_at FROM users
WHERE ($1::text IS NULL OR status = $1::text)
  AND ($2::text IS NULL
       OR username ILIKE '%' || $2::text || '%'
       OR email ILIKE '%' || $2::text || '%'
       OR full_name ILIKE '%' || $2::text || '%'
       OR first_name ILIKE '%' || $2::text || '%')
ORDER BY status = 'pending' DESC, lower(full_name), id
`

